import { DashboardShell, MetricCard } from '../../components/dashboard-shell';
import { DashboardState } from '../../components/dashboard-state';
import { apiGet } from '../../lib/server-api';
type VendorData={business:{id:string;name:string;slug:string;status:string;completionPercent:number;publicVisible:boolean};metrics:{newLeads:number;totalLeads:number;responses:number;credits:number;portfolioPosts:number;reviews:number;badges:number};leads:Array<{id:string;status:string;eventType:string;eventDate:string;city:string;category:string;budgetMin:string|null;budgetMax:string|null;createdAt:string}>};
const money=(value:string|null)=>value?`₹${Number(value).toLocaleString('en-IN')}`:'Not specified';
export default async function VendorDashboard(){const result=await apiGet<VendorData>('/dashboard/vendor');return <DashboardShell role="vendor" active="Overview" eyebrow="Studio overview" title={result.ok?result.data.business.name:'Vendor workspace'} actions={<a className="dash-secondary" href="/vendor/onboarding">Edit profile</a>}>{!result.ok?<DashboardState title={result.status===404?'Create your business profile':'Open your vendor workspace'} message={result.status===404?'Your account is verified. Complete onboarding to create and publish your business profile.':result.message} role="VENDOR_OWNER"/>:<><section className="vendor-status"><div className="status-copy"><span className="verified-mark">{result.data.business.publicVisible?'✓':'◎'}</span><div><strong>{result.data.business.publicVisible?'Your profile is live':`Profile status: ${result.data.business.status.toLowerCase().replaceAll('_',' ')}`}</strong><p>Complete remaining onboarding steps before submitting for review.</p></div></div><div className="profile-score"><span><b style={{width:`${result.data.business.completionPercent}%`}}/></span><strong>{result.data.business.completionPercent}%</strong></div><a href="/vendor/onboarding">Complete profile →</a></section><section className="metric-grid"><MetricCard label="New leads" value={String(result.data.metrics.newLeads)} detail={`${result.data.metrics.totalLeads} total opportunities`}/><MetricCard label="Responses" value={String(result.data.metrics.responses)} detail="Lead conversations started" tone="gold"/><MetricCard label="Portfolio posts" value={String(result.data.metrics.portfolioPosts)} detail={`${result.data.metrics.reviews} customer reviews`} tone="green"/><MetricCard label="Lead credits" value={String(result.data.metrics.credits)} detail="Credits available" tone="blue"/></section><section className="dash-card"><div className="card-heading"><div><p className="dash-kicker">Live from Supabase</p><h2>Recent leads</h2></div><a href="/vendor/leads">View all →</a></div>{result.data.leads.length?<div className="lead-table"><div className="table-head"><span>Requirement</span><span>Budget</span><span>Status</span></div>{result.data.leads.map(lead=><a href={`/vendor/leads?lead=${lead.id}`} key={lead.id}><div><strong>{lead.category} · {lead.eventType}</strong><p>{lead.city} · {new Date(lead.eventDate).toLocaleDateString('en-IN',{dateStyle:'medium'})}</p></div><span>{money(lead.budgetMin)}–{money(lead.budgetMax)}</span><b className={lead.status==='NEW'?'new':''}>{lead.status}</b></a>)}</div>:<div className="compact-empty"><span>↗</span><h3>No leads yet</h3><p>New matching customer requirements will appear here automatically.</p></div>}</section></>}</DashboardShell>}
